package com.hrm.service;
import com.hrm.security.AuthenticatedAccount;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class DepartmentWorkspaceAccessTest {
 final AuthenticatedAccount head=new AuthenticatedAccount(4L,7L,"head","EMPLOYEE");
 @Test void ordinaryEmployeeAndForgedRoleCannotAcquireHeadScope(){var db=mock(JdbcTemplate.class);var access=new DepartmentWorkspaceAccess(db);when(db.queryForList(anyString(),eq(String.class),eq(4L),eq(7L))).thenReturn(List.of("EMPLOYEE"));assertThrows(ResponseStatusException.class,()->access.departments(head));assertThrows(ResponseStatusException.class,()->access.departments(new AuthenticatedAccount(4L,7L,"head","ADMIN")));}
 @Test void outOfScopeAndOwnScheduleWritesAreDenied(){var db=mock(JdbcTemplate.class);var access=spy(new DepartmentWorkspaceAccess(db));doReturn(List.of(3L)).when(access).departments(head);when(db.queryForObject(anyString(),eq(Long.class),eq(9L),any(LocalDate.class),any(LocalDate.class))).thenReturn(0L);assertThrows(ResponseStatusException.class,()->access.employee(head,9,LocalDate.now(),true));when(db.queryForObject(anyString(),eq(Long.class),eq(7L),any(LocalDate.class),any(LocalDate.class))).thenReturn(1L);assertThrows(ResponseStatusException.class,()->access.employee(head,7,LocalDate.now(),true));verify(db,never()).update(anyString(),any(Object[].class));}
 @Test void missingDepartmentApprovalBlocksFinalApproval(){var db=mock(JdbcTemplate.class);var service=spy(new DepartmentReviewService(db,mock(DepartmentWorkspaceAccess.class),mock(NotificationPublisher.class)));var row=new HashMap<String,Object>();row.put("employee_id",9L);row.put("starts",java.sql.Timestamp.valueOf("2026-11-10 18:00:00"));row.put("fingerprint","v1");doReturn(row).when(service).source("OT",15);when(db.queryForObject(contains("SELECT COUNT_BIG(*) FROM dbo.employee_assignments"),eq(Long.class),any(Object[].class))).thenReturn(1L);when(db.queryForObject(contains("SELECT COUNT_BIG(*) FROM dbo.department_workflow_reviews"),eq(Long.class),any(Object[].class))).thenReturn(0L);assertThrows(ResponseStatusException.class,()->service.requireApproval("OT",15));}
 @Test void changedRequestCannotBeApprovedFromStaleScreen(){var db=mock(JdbcTemplate.class);var service=spy(new DepartmentReviewService(db,mock(DepartmentWorkspaceAccess.class),mock(NotificationPublisher.class)));doReturn(Map.of("fingerprint","new")).when(service).source("OT",15);assertThrows(ResponseStatusException.class,()->service.decide(head,"OT",15,true,"Reviewed","old"));verify(db,never()).update(anyString(),any(Object[].class));}
}
